package ir.neshane.isolationprobe.recovery;

import static ir.neshane.isolationprobe.recovery.LabRecoveryTrust.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Trusted host harness only: fixed backup/restore tools, no workload-provided commands. */
final class BackupRestore {
    private final Path scratch,evidence;
    private final String source,target,run;
    BackupRestore(Path scratch,Path evidence,String source,String target,String run){this.scratch=scratch;this.evidence=evidence;this.source=source;this.target=target;this.run=run;}
    String command(List<String> args)throws Exception{require(args.getFirst().equals("docker"),"TOOL_ALLOWLIST");var p=new ProcessBuilder(args).redirectErrorStream(true).start();byte[] data=p.getInputStream().readAllBytes();boolean ended=p.waitFor(90,TimeUnit.SECONDS);String output=new String(data,StandardCharsets.UTF_8).strip();if(!ended||p.exitValue()!=0){Files.writeString(evidence.resolve("backup-tool-failures.tsv"),args+"\t"+output.replace('\n',' ')+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);throw new Denied("BACKUP_RESTORE_TOOL_FAILED:"+args.get(1));}return output;}
    private void exportPrivate(String node,String remote,Path local)throws Exception{require(node.equals(source)&&remote.matches("/tmp/backup-[a-f0-9-]{36}\\.dump")&&local.normalize().getParent().equals(scratch),"PRIVATE_ARCHIVE_PATH");var p=new ProcessBuilder("docker","exec",node,"cat",remote).start();var error=java.util.concurrent.CompletableFuture.supplyAsync(()->{try{return new String(p.getErrorStream().readAllBytes(),StandardCharsets.UTF_8);}catch(IOException failure){throw new java.io.UncheckedIOException(failure);}});try(var out=Files.newOutputStream(local,StandardOpenOption.CREATE_NEW)){p.getInputStream().transferTo(out);}require(p.waitFor(90,TimeUnit.SECONDS)&&p.exitValue()==0,"PRIVATE_ARCHIVE_EXPORT_FAILED:"+error.get());require(command(List.of("docker","exec",node,"sha256sum",remote)).split("\\s+")[0].equals(hash(Files.readAllBytes(local))),"EXPORTED_ARCHIVE_HASH_MISMATCH");}
    private void importPrivate(Path local,String node,String remote)throws Exception{require(node.equals(target)&&local.normalize().getParent().equals(scratch)&&remote.matches("/tmp/drref-restore-[ab]\\.dump"),"PRIVATE_ARCHIVE_PATH");var p=new ProcessBuilder("docker","exec","-i",node,"tee",remote).start();var output=java.util.concurrent.CompletableFuture.runAsync(()->{try{p.getInputStream().transferTo(OutputStream.nullOutputStream());}catch(IOException failure){throw new java.io.UncheckedIOException(failure);}});var error=java.util.concurrent.CompletableFuture.supplyAsync(()->{try{return new String(p.getErrorStream().readAllBytes(),StandardCharsets.UTF_8);}catch(IOException failure){throw new java.io.UncheckedIOException(failure);}});try(var in=Files.newInputStream(local);var out=p.getOutputStream()){in.transferTo(out);}require(p.waitFor(90,TimeUnit.SECONDS)&&p.exitValue()==0,"PRIVATE_ARCHIVE_IMPORT_FAILED:"+error.get());output.get();}
    void owned(String id)throws Exception{require(id.matches("[a-f0-9]{64}"),"CONTAINER_ID");require(command(List.of("docker","inspect","--format","{{json .Config.Labels}}",id)).contains("\"neshane.drref\":\""+run+"\""),"RUN_OWNERSHIP");}
    String sql(String node,String database,String statement)throws Exception{require(node.equals(source)||node.equals(target),"OWNED_DATABASE_ONLY");require(Set.of("dr_a","dr_b","postgres").contains(database),"DATABASE_ALLOWLIST");var p=new ProcessBuilder("docker","exec","-i","--env","PGPASSFILE=/tmp/pgpass",node,"psql","-X","-w","-h","/tmp","-U","postgres","-d",database,"-v","ON_ERROR_STOP=1","-At").redirectErrorStream(true).start();p.getOutputStream().write(statement.getBytes(StandardCharsets.UTF_8));p.getOutputStream().close();byte[] data=p.getInputStream().readAllBytes();require(p.waitFor(30,TimeUnit.SECONDS)&&p.exitValue()==0,"INDEPENDENT_SQL_FAILURE");return new String(data,StandardCharsets.UTF_8).strip();}
    Map<String,String> backup(String cell)throws Exception{require(Set.of("a","b").contains(cell),"CELL_ALLOWLIST");owned(source);long start=System.nanoTime();String id="backup-"+UUID.randomUUID();String remote="/tmp/"+id+".dump";Path local=scratch.resolve(id+".dump");command(List.of("docker","exec","--env","PGPASSFILE=/tmp/pgpass",source,"pg_dump","-h","/tmp","-U","postgres","-d","dr_"+cell,"--schema=lab_data","--no-owner","--no-privileges","--format=custom","--file",remote));exportPrivate(source,remote,local);command(List.of("docker","exec",source,"rm",remote));require(Files.size(local)>0,"EMPTY_BACKUP");var result=map("backup",id,"archive-digest",hash(Files.readAllBytes(local)),"bytes",""+Files.size(local),"duration-nanos",""+(System.nanoTime()-start));Files.writeString(evidence.resolve(id+".observation"),result+"\n");return result;}
    Path archive(Map<String,String> m){require(m.get("backup").matches("backup-[a-f0-9-]{36}"),"BACKUP_ID_FORMAT");return scratch.resolve(m.get("backup")+".dump");}
    void verifyArchive(Map<String,String> m)throws Exception{Path archive=archive(m);require(Files.isRegularFile(archive)&&hash(Files.readAllBytes(archive)).equals(m.get("archive-digest")),"BACKUP_INTEGRITY");}
    void restore(String cell,Map<String,String> manifest)throws Exception{
        require(Set.of("a","b").contains(cell)&&manifest.get("tenant").equals("tenant-"+cell)&&manifest.get("cell").equals("cell-"+cell),"RESTORE_TENANT_CELL");owned(target);verifyArchive(manifest);long start=System.nanoTime();
        Path original=archive(manifest),sealed=scratch.resolve("restore-"+UUID.randomUUID()+".dump");Files.copy(original,sealed);require(hash(Files.readAllBytes(sealed)).equals(manifest.get("archive-digest")),"ARCHIVE_CHANGED_AFTER_VALIDATION");String remote="/tmp/drref-restore-"+cell+".dump";importPrivate(sealed,target,remote);String digest=command(List.of("docker","exec",target,"sha256sum",remote)).split("\\s+")[0];require(digest.equals(manifest.get("archive-digest")),"EXACT_RESTORE_ARCHIVE_BINDING");
        sql(target,"dr_"+cell,"UPDATE recovery.gate SET state='QUARANTINED',acknowledged=false,attempt_id=NULL,data_digest=NULL; DROP SCHEMA lab_data CASCADE;");
        command(List.of("docker","exec","--env","PGPASSFILE=/tmp/pgpass",target,"pg_restore","-h","/tmp","-U","postgres","-d","dr_"+cell,"--no-owner","--no-privileges","--exit-on-error",remote));
        sql(target,"dr_"+cell,"GRANT USAGE ON SCHEMA lab_data TO owner_"+cell+",runtime_"+cell+"; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA lab_data TO owner_"+cell+"; GRANT SELECT ON ALL TABLES IN SCHEMA lab_data TO runtime_"+cell+";");
        command(List.of("docker","exec",target,"rm",remote));Files.delete(sealed);require(sql(target,"dr_"+cell,"SELECT state||'|'||acknowledged FROM recovery.gate;").equals("QUARANTINED|false"),"RESTORED_GATE_NOT_QUARANTINED");Files.writeString(evidence.resolve("restore-observations.tsv"),manifest.get("backup")+"\ttenant-"+cell+"\tcell-"+cell+"\t"+manifest.get("archive-digest")+"\t"+(System.nanoTime()-start)+"\tQUARANTINED\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);
    }
    String independentState(String cell)throws Exception{return sql(target,"dr_"+cell,"SELECT json_build_object('gate',(SELECT row_to_json(g) FROM recovery.gate g),'identity',(SELECT json_agg(i) FROM lab_data.identity i),'markers',(SELECT json_agg(m ORDER BY marker_id) FROM lab_data.markers m),'operations',(SELECT json_agg(o ORDER BY sequence) FROM lab_data.operations o),'outbox',(SELECT json_agg(x ORDER BY operation_id) FROM lab_data.outbox x),'audit',(SELECT json_agg(a ORDER BY event_id) FROM recovery.audit a))::text;");}
    String sourceState(String cell)throws Exception{return sql(source,"dr_"+cell,"SELECT json_build_object('markers',(SELECT json_agg(m ORDER BY marker_id) FROM lab_data.markers m),'operations',(SELECT json_agg(o ORDER BY sequence) FROM lab_data.operations o),'audit',(SELECT json_agg(a ORDER BY event_id) FROM recovery.audit a))::text;");}
}
